import { mkdir, open, rename, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { Readable } from "node:stream";
import { AwsClient } from "aws4fetch";
import { and, eq, sql } from "drizzle-orm";
import type { Config } from "./config.ts";
import { storageDeletion } from "./db/schema.ts";
import type { Database } from "./db/tenant.ts";
import { retryDelayMs } from "./retry.ts";

/** Where image bytes live. A key is always generated by the server, never taken from a request. */
export interface ObjectStore {
  put(key: string, bytes: Uint8Array, contentType: string, signal?: AbortSignal): Promise<void>;
  /** Returns null if the object does not exist. */
  get(key: string, signal?: AbortSignal): Promise<ReadableStream<Uint8Array> | null>;
  delete(key: string, signal?: AbortSignal): Promise<void>;
}

/** How long one call to the object store may wait for its answer. */
const STORE_TIMEOUT_MS = 30_000;

export function localStore(directory: string): ObjectStore {
  return {
    async put(key, bytes) {
      const path = join(directory, key);
      await mkdir(dirname(path), { recursive: true });
      // Through a temporary name, so a crash cannot leave a partial image.
      const temporary = `${path}.${process.pid}.tmp`;
      await writeFile(temporary, bytes);
      await rename(temporary, path);
    },
    async get(key) {
      try {
        const file = await open(join(directory, key));
        return Readable.toWeb(file.createReadStream()) as ReadableStream<Uint8Array>;
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw error;
      }
    },
    async delete(key) {
      await rm(join(directory, key), { force: true });
    },
  };
}

interface S3Options {
  endpoint: string;
  region: string;
  bucket: string;
  accessKeyId: string;
  secretAccessKey: string;
  timeoutMs?: number;
}

export function s3Store({
  endpoint,
  region,
  bucket,
  accessKeyId,
  secretAccessKey,
  timeoutMs = STORE_TIMEOUT_MS,
}: S3Options) {
  const client = new AwsClient({ accessKeyId, secretAccessKey, region, service: "s3" });
  const url = (key: string) => `${endpoint.replace(/\/$/, "")}/${bucket}/${key}`;
  /**
   * A store that accepts a connection and never answers would hold an upload's byte budget, or a
   * worker's slot, until undici's 300-second default. The timer bounds the wait for the answer's
   * headers only, so a large image still streams to a slow client.
   */
  const call = async (key: string, init: RequestInit, signal: AbortSignal | undefined) => {
    const timeout = new AbortController();
    const timer = setTimeout(
      () => timeout.abort(new Error("The object store did not answer in time")),
      timeoutMs,
    );
    try {
      return await client.fetch(url(key), {
        ...init,
        signal: signal === undefined ? timeout.signal : AbortSignal.any([signal, timeout.signal]),
      });
    } finally {
      clearTimeout(timer);
    }
  };
  const store: ObjectStore = {
    async put(key, bytes, contentType, signal) {
      const response = await call(
        key,
        {
          method: "PUT",
          body: bytes as Uint8Array<ArrayBuffer>,
          headers: { "content-type": contentType },
        },
        signal,
      );
      if (!response.ok) throw new Error(`The object store answered ${response.status}`);
    },
    async get(key, signal) {
      const response = await call(key, {}, signal);
      if (response.status === 404) return null;
      if (!response.ok) throw new Error(`The object store answered ${response.status}`);
      return response.body;
    },
    async delete(key, signal) {
      const response = await call(key, { method: "DELETE" }, signal);
      if (!response.ok && response.status !== 404) {
        throw new Error(`The object store answered ${response.status}`);
      }
    },
  };
  return store;
}

export function storeFromConfig(config: Config): ObjectStore {
  if (config.S3_BUCKET === undefined) return localStore(config.STORAGE_DIR);
  const { S3_ENDPOINT, S3_ACCESS_KEY_ID, S3_SECRET_ACCESS_KEY } = config;
  if (
    S3_ENDPOINT === undefined ||
    S3_ACCESS_KEY_ID === undefined ||
    S3_SECRET_ACCESS_KEY === undefined
  ) {
    throw new Error("S3_BUCKET needs S3_ENDPOINT, S3_ACCESS_KEY_ID and S3_SECRET_ACCESS_KEY.");
  }
  return s3Store({
    endpoint: S3_ENDPOINT,
    region: config.S3_REGION,
    bucket: config.S3_BUCKET,
    accessKeyId: S3_ACCESS_KEY_ID,
    secretAccessKey: S3_SECRET_ACCESS_KEY,
  });
}

// The queue of files to delete from the store: from moderation, a workspace's purge, image
// retention and a failed import. The worker claims from it.

export interface ClaimedDeletion {
  workspaceId: string;
  id: string;
  storageKey: string;
  attempts: number;
}

/** Claims due deletions and commits, so no transaction stays open during a call to the store. */
export async function claimDeletions(
  db: Database,
  limit: number,
  claimMs: number,
): Promise<ClaimedDeletion[]> {
  const result = await db.execute<{
    workspace_id: string;
    id: string;
    storage_key: string;
    attempts: number;
  }>(sql`
    WITH due AS MATERIALIZED (
      SELECT workspace_id, id FROM storage_deletion
      WHERE next_attempt_at <= now() AND (claimed_until IS NULL OR claimed_until < now())
      ORDER BY next_attempt_at
      LIMIT ${limit}
      FOR UPDATE SKIP LOCKED
    )
    UPDATE storage_deletion AS row
    SET attempts = row.attempts + 1,
        claimed_until = now() + ${claimMs}::float8 * interval '1 millisecond'
    FROM due
    WHERE row.workspace_id = due.workspace_id AND row.id = due.id
    RETURNING row.workspace_id, row.id, row.storage_key, row.attempts`);
  return result.rows.map((row) => ({
    workspaceId: row.workspace_id,
    id: row.id,
    storageKey: row.storage_key,
    attempts: row.attempts,
  }));
}

export async function finishDeletion(db: Database, row: ClaimedDeletion): Promise<void> {
  await db
    .delete(storageDeletion)
    .where(and(eq(storageDeletion.workspaceId, row.workspaceId), eq(storageDeletion.id, row.id)));
}

/** It never gives up, because a file that stays after its delete breaks the promise of a delete. */
export async function retryDeletion(
  db: Database,
  row: ClaimedDeletion,
  retryMs: number,
): Promise<void> {
  const wait = retryDelayMs(retryMs, row.attempts);
  await db
    .update(storageDeletion)
    .set({ claimedUntil: null, nextAttemptAt: new Date(Date.now() + wait) })
    .where(and(eq(storageDeletion.workspaceId, row.workspaceId), eq(storageDeletion.id, row.id)));
}
